const raw = $input.first().json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const mediaId = String(body.mediaId || '').trim();
if (!/^\d{8,}$/.test(mediaId)) throw new Error('Άκυρο Instagram media id');
return [{ json: { mediaId } }];

const row = $input.first().json || {};
const text = JSON.stringify(row).toLowerCase();
const failed = !!(row.error || row.errorMessage);
if (failed) {
  const gone = text.includes('does not exist') || text.includes('bad request') || text.includes('unsupported delete') || text.includes('not found');
  if (!gone) throw new Error(row.error?.message || row.message || 'Το Instagram story δεν σβήστηκε.');
  return [{ json: { ok: true, gone: true } }];
}
return [{ json: { ok: true, gone: false } }];
